style.css:
@-moz-document domain("barsupplies.com") {
/* ============================================================
   BARSUPPLIES.COM | MIDNIGHT BLUE DARK MODE v2.2
   Single consolidated stylesheet | Stylish / Userstyles.org
   Palette: midnight navy, electric blue, white typography.
   Includes green-accent cleanup + white logo + moon indicator.
   ============================================================ */

/* 01. THEME TOKENS */
:root {
  color-scheme: dark;
  --bs-bg: #070f17;
  --bs-header: #09131d;
  --bs-nav: #101b26;
  --bs-panel: #0d1924;
  --bs-raised: #162431;
  --bs-hover: #203448;
  --bs-border: #263b4d;
  --bs-white: #f5f8fc;
  --bs-text: #dce5ef;
  --bs-muted: #acbccd;
  --bs-blue: #168dfa;
  --bs-blue-light: #65baff;
  --bs-sale: #ff968b;

  /* Warehouse / Shopify theme properties */
  --background: var(--bs-bg);
  --card-background: var(--bs-panel);
  --text-color: var(--bs-text);
  --heading-color: var(--bs-white);
  --border-color: var(--bs-border);
  --header-background: var(--bs-header);
  --header-text-color: var(--bs-white);
  --navigation-background: var(--bs-nav);
  --navigation-text-color: var(--bs-text);
  --footer-background: var(--bs-bg);
  --footer-text-color: var(--bs-muted);
}

/* 02. PAGE + TYPOGRAPHY */
html, body, main, #MainContent, .main-content,
.page-container, .page-content, .page-width,
.shopify-section__main, .layout, .container--flush {
  background-color: var(--bs-bg) !important;
  color: var(--bs-text) !important;
}
body { color-scheme: dark !important; }
h1, h2, h3, h4, h5, h6,
.heading, .section__title, .section__header,
.card__title, .product-meta__title {
  color: var(--bs-white) !important;
}
p, li, dt, dd, .rte, .prose, .description {
  color: var(--bs-text);
}
a { color: var(--bs-blue); }
a:hover { color: var(--bs-blue-light); }

/* 03. HEADER + TOP BAR */
.header, .header__inner, .header__wrapper, .header__top,
.header__bottom, .header__search-bar-wrapper,
.header__action-list, .shopify-section--header {
  background-color: var(--bs-header) !important;
  color: var(--bs-white) !important;
  border-color: var(--bs-border) !important;
}
.announcement-bar, .top-bar, .header__top-bar,
.header__announcement-bar {
  background-color: #07111b !important;
  color: var(--bs-muted) !important;
  border-color: var(--bs-border) !important;
}
.header a, .header button, .header .icon,
.header__action-item, .header__action-item-title,
.header__icon-wrapper {
  color: var(--bs-white) !important;
}
.header a:hover, .header button:hover {
  color: var(--bs-blue-light) !important;
}

/* 04. BRAND LOGO: WHITE + SOFT BLUE HALO
   Applies only to the actual header logo, not product imagery. */
.header__logo img, .header__logo-image,
.header__logo-image img, .header-logo__image img,
.site-header__logo img {
  filter: brightness(0) invert(1)
          drop-shadow(0 0 4px rgba(255,255,255,.33))
          drop-shadow(0 0 10px rgba(22,141,250,.40)) !important;
  opacity: 1 !important;
}

/* Moon / status label below the logo; decorative, non-interactive.
   A single pseudo-element avoids the overlapping earlier patches. */
.header__logo, .header-logo, .site-header__logo {
  position: relative !important;
  overflow: visible !important;
}
.header__logo::after, .header-logo::after,
.site-header__logo::after {
  content: "☾  DARK MODE ENABLED";
  position: absolute;
  left: 4px;
  bottom: -17px;
  z-index: 2;
  display: block;
  color: #8ccaff !important;
  font: 700 10px/1.2 Arial, sans-serif !important;
  letter-spacing: 1.9px;
  white-space: nowrap;
  text-shadow: 0 0 7px rgba(22,141,250,.55);
  pointer-events: none;
}

/* 05. NAVIGATION + MEGA MENU */
.nav-bar, .nav-bar__inner, .navigation, .site-nav,
.header__menu, .header__inline-menu,
.mobile-menu, .mobile-menu__inner, .mobile-menu__section {
  background-color: var(--bs-nav) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.nav-bar a, .nav-bar__link, .site-nav a,
.navigation a, .mobile-menu a {
  color: var(--bs-blue-light) !important;
}
.nav-bar a:hover, .site-nav a:hover,
.navigation a:hover, .mobile-menu a:hover {
  color: var(--bs-white) !important;
}
.mega-menu, .mega-menu__inner, .mega-menu__column,
.dropdown-menu, .dropdown-menu__item, .nav-dropdown,
.popover, .popover__inner, .popover__content,
.menu-drawer, .menu-drawer__inner-container {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.mega-menu a, .dropdown-menu a, .nav-dropdown a,
.popover a, .menu-drawer a {
  color: var(--bs-text) !important;
}
.mega-menu a:hover, .dropdown-menu a:hover,
.nav-dropdown a:hover, .popover a:hover,
.menu-drawer a:hover {
  color: var(--bs-blue-light) !important;
}

/* 06. SEARCH */
.search-bar, .search-bar__inner, .search-bar__input,
.search-bar__filter, .search-bar__results,
.search-bar__result-item, .predictive-search,
.predictive-search__results, .search-results,
.search-modal, .search-modal__content {
  background-color: var(--bs-raised) !important;
  color: var(--bs-white) !important;
  border-color: var(--bs-border) !important;
}
.search-bar__result-item:hover,
.predictive-search__item:hover {
  background-color: var(--bs-hover) !important;
}
input::placeholder, textarea::placeholder {
  color: var(--bs-muted) !important;
  opacity: 1 !important;
}

/* 07. PRODUCT GRIDS + COLLECTION CARDS */
.card, .card__header, .card__section, .card__footer,
.product-item, .product-item__info, .product-card,
.product-grid-item, .collection-item, .collection-list__item,
.featured-collection, .featured-product, .article-item,
.blog-post-card {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.product-list, .product-grid, .collection, .collection__inner,
.collection__main, .product,
.shopify-section--featured-collection,
.shopify-section--collection-list {
  background-color: var(--bs-bg) !important;
}
.product-item__title, .product-item__title a,
.product-card__title, .product-card__title a,
.collection-item__title, .article-item__title {
  color: var(--bs-white) !important;
}
.product-item__title a:hover,
.product-card__title a:hover {
  color: var(--bs-blue-light) !important;
}
.product-item__price-list, .product-item__price,
.price, .price-list, .product-meta__price-list {
  color: var(--bs-white) !important;
}
.price--highlight, .price--sale, .product-price--sale {
  color: var(--bs-sale) !important;
}
.price--compare, .product-item__vendor,
.product-meta__vendor, .product-meta__reference {
  color: var(--bs-muted) !important;
}

/* 08. PRODUCT DETAIL PANELS + TABS */
.product-block-list, .product-block-list__item,
.product-form, .product-meta, .product__info,
.product__info-container, .product__description,
.product-tabs, .tabs, .tabs__content, .tabs__nav,
.accordion, .collapsible, .collapsible-content,
.product-form__option-selector {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.tabs__tab, .tabs__nav-item, .accordion__toggle,
.collapsible-toggle, .product-form__option-name,
.product-form__quantity-label {
  color: var(--bs-text) !important;
}

/* 09. COLLECTION SIDE MENU + FILTERS
   Force link colors in the sidebar so green active categories
   cannot leak through the original theme styling. */
.collection__toolbar, .collection__filter-group,
.collection__filter, .collection__sort-by,
.collection__sidebar, .sidebar, .sidebar__block,
.filter, .filter-group, .facets, .facet-filters,
.active-facets, .filter-drawer, .collection-filters {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.collection__sidebar a, .sidebar a,
.sidebar__linklist a, .sidebar__linklist-item a,
.linklist__item a, .filter a, .facets a {
  color: var(--bs-text) !important;
}
.collection__sidebar a:hover, .sidebar a:hover,
.sidebar__linklist a:hover, .linklist__item a:hover,
.filter a:hover, .facets a:hover {
  color: var(--bs-blue-light) !important;
}
/* Active/expanded/current navigation replaces green with blue */
.sidebar__linklist [aria-current="page"],
.sidebar__linklist [aria-expanded="true"],
.sidebar__linklist-item--active > a,
.sidebar__linklist-item.is-active > a,
.sidebar__linklist-item.active > a,
.linklist__item--active > a,
.linklist__item.is-active > a,
.collection__sidebar a[aria-current="page"],
.collection__sidebar a[aria-expanded="true"],
.collection__sidebar .is-active > a,
.collection__sidebar .active > a,
.sidebar .is-active > a,
.sidebar .active > a {
  color: var(--bs-blue) !important;
  font-weight: 600 !important;
}
/* In some navigation trees active text is a span, not a link. */
.sidebar__linklist-item--active > span,
.sidebar__linklist .is-active > span,
.collection__sidebar .is-active > span,
.sidebar .is-active > span {
  color: var(--bs-blue) !important;
}
.sidebar .icon, .collection__sidebar .icon,
.sidebar__linklist svg, .collection__sidebar svg {
  color: var(--bs-blue-light) !important;
}

/* 10. INPUTS + OPTIONS */
input:not([type="checkbox"]):not([type="radio"]):not([type="image"]),
textarea, select, .form__field, .form__input, .input,
.quantity-selector, .quantity-selector__value,
.select-wrapper {
  background-color: var(--bs-raised) !important;
  color: var(--bs-white) !important;
  border: 1px solid var(--bs-border) !important;
}
input:focus-visible, textarea:focus-visible,
select:focus-visible {
  outline: 2px solid var(--bs-blue) !important;
  outline-offset: 1px;
}
input[type="checkbox"], input[type="radio"] {
  accent-color: var(--bs-blue) !important;
}
.form__label, .option-selector__label, label {
  color: var(--bs-text) !important;
}
option, optgroup {
  background-color: var(--bs-raised) !important;
  color: var(--bs-white) !important;
}

/* 11. ELECTRIC BLUE BUTTONS */
.button--primary, .btn--primary,
.product-form__add-button,
.product-item__action-button--list,
.cart-recap__checkout,
.shopify-payment-button__button--unbranded {
  background-color: var(--bs-blue) !important;
  border-color: var(--bs-blue) !important;
  color: #fff !important;
}
.button--primary:hover, .btn--primary:hover,
.product-form__add-button:hover,
.product-item__action-button--list:hover,
.cart-recap__checkout:hover,
.shopify-payment-button__button--unbranded:hover {
  background-color: #369fff !important;
  border-color: #369fff !important;
  color: #fff !important;
}
.button--secondary, .btn--secondary, .button--ternary,
.product-item__action-button:not(.product-item__action-button--list),
.quantity-selector__button {
  background-color: var(--bs-raised) !important;
  border-color: var(--bs-border) !important;
  color: var(--bs-white) !important;
}
.button--secondary:hover, .btn--secondary:hover,
.button--ternary:hover, .quantity-selector__button:hover {
  background-color: var(--bs-hover) !important;
}

/* 12. CART + MODALS + ACCOUNT */
.cart, .cart__content, .cart__item, .cart__footer,
.cart-recap, .cart-recap__price-line,
.cart-drawer, .mini-cart, .drawer, .drawer__header,
.drawer__content, .drawer__footer, .modal,
.modal__dialog, .modal__inner, .quick-view,
.quick-view__content, .account, .account__content,
.customer, .customer__inner, .login, .login__form {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
.cart a, .drawer a, .modal a {
  color: var(--bs-blue-light) !important;
}
.drawer__close, .modal__close { color: var(--bs-white) !important; }

/* 13. TABLES, BREADCRUMBS, PAGINATION */
table, thead, tbody, tr, th, td,
.pagination, .pagination__inner, .pagination__nav,
.pagination__text {
  background-color: var(--bs-panel) !important;
  color: var(--bs-text) !important;
  border-color: var(--bs-border) !important;
}
th { background-color: var(--bs-nav) !important; }
.pagination a { color: var(--bs-blue-light) !important; }
.breadcrumb, .breadcrumb__list, .breadcrumb__link,
.text--subdued, .product-item__inventory {
  color: var(--bs-muted) !important;
}
hr, .separator, .divider { border-color: var(--bs-border) !important; }

/* 14. FOOTER */
.footer, .footer__inner, .footer__block,
.footer__aside, .footer__newsletter,
.footer__copyright, .shopify-section--footer,
.newsletter, .newsletter-section {
  background-color: #08121b !important;
  color: var(--bs-muted) !important;
  border-color: var(--bs-border) !important;
}
.footer h2, .footer h3, .footer__title,
.footer__block-title { color: var(--bs-white) !important; }
.footer a { color: var(--bs-text) !important; }
.footer a:hover { color: var(--bs-blue-light) !important; }

/* 15. IMAGES: KEEP PRODUCT PHOTOGRAPHY UNCHANGED
   Deliberately NO .header img reset, which would break white logo. */
.product-item img, .product-gallery img,
.product__media img, .product-card img,
.slideshow img, .banner img,
.collection-item img {
  filter: none !important;
  opacity: 1 !important;
}

/* 16. SELECTION + SCROLLBARS */
::selection { background: #155a9b; color: #fff; }
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background-color: var(--bs-bg); }
::-webkit-scrollbar-thumb {
  background-color: #2b4052;
  border: 2px solid var(--bs-bg);
  border-radius: 8px;
}
::-webkit-scrollbar-thumb:hover { background-color: #45647c; }

/* Small screens: avoid moon label colliding with nearby controls. */
@media (max-width: 640px) {
  .header__logo::after, .header-logo::after,
  .site-header__logo::after {
    font-size: 8px !important;
    letter-spacing: 1px;
    bottom: -13px;
    left: 0;
  }
}
}
